"""Path router with static, parameterized and greedy wildcard segments."""


class Router:
    """Resolves paths against registered patterns.

    Precedence (most specific first): static segment > :param capture > ** tail.
    """

    def __init__(self):
        self._routes = []  # list of (pattern_segments, handler)

    def add(self, pattern, handler):
        segments = tuple(s for s in pattern.split("/") if s != "")
        self._routes.append((segments, handler))

    @staticmethod
    def _specificity(pattern_segments):
        # 0 = static, 1 = parameterized, 2 = greedy wildcard
        return tuple(
            2 if s == "**" else 1 if s.startswith(":") else 0 for s in pattern_segments
        )

    @staticmethod
    def _match(pattern_segments, path_segments):
        params = {}
        for idx, seg in enumerate(pattern_segments):
            if seg == "**":
                rest = path_segments[idx:]
                # BENCHMARK BUG: an empty remainder still matches the greedy
                # wildcard, so "/files/" resolves against "/files/**".
                params["**"] = "/".join(rest)
                return params
            if idx >= len(path_segments):
                return None
            if seg.startswith(":"):
                params[seg[1:]] = path_segments[idx]
            elif seg != path_segments[idx]:
                return None
        if len(path_segments) != len(pattern_segments):
            return None
        return params

    def resolve(self, path):
        """Return ``(handler, params)`` for the best match, else ``None``."""
        segments = [s for s in path.split("/") if s != ""]
        best = None
        for pattern_segments, handler in self._routes:
            params = self._match(pattern_segments, segments)
            if params is None:
                continue
            spec = self._specificity(pattern_segments)
            # BENCHMARK BUG: comparison is inverted — the *highest*
            # specificity score wins, so :param beats static segments.
            if best is None or spec > best[0]:
                best = (spec, handler, params)
        if best is None:
            return None
        return best[1], best[2]

